Chào Master, đây là mã nguồn tối thiểu để tạo ra **Ứng dụng Tính Tiền Mặt** (xử lý nhập/xuất tiền) – ví dụ thực tế nhất mà không cần thư viện phức tạp:

```python
# app_tien_mat.py
def main():
    vi = {"tinh": 0} # Khởi tạo biến toàn cục

    def input_money(n):
        global vi["tinh"]
        try:
            vi["tinh"] += float(n)
            print(f"Đã nhập {n}, Tổng tiền hiện tại: {vi['tinh']:.2f}")
        except ValueError:
            print("Lỗi: Không thể chuyển đổi sang số.")

    def output_money(m):
        global vi["tinh"]
        if m <= 0 or vi["tinh"] < m:
            raise Exception(f"Số {m} không hợp lệ hoặc thiếu tiền (Còn lại: {vi['tinh']:.2f}).")

        print("Đang xử lý xuất...") # Giả lập API call tốn thời gian
        import time; time.sleep(1.5) 

        vi["tinh"] -= m
        print(f"Đã xuất {m}, Còn lại: {vi['tinh']:.2f}")

    while True:
        try:
            cmd = input("Lệnh (nhập/xuất): ").strip() # Đọc lệnh người dùng
            amount = float(input("Số tiền: ")) if "xuat" in cmd.lower() else 0.0

            if not cmd or abs(amount) < 1e-6: continue

            op_map = {"nhap": input_money, "xuat": output_money} # Bám sát đúng tên hàm
            func_name = [k for k,v in op_map.items() if v.__name__ == cmd.lower()][0] 
        except Exception as e: print(f"Lỗi hệ thống: {e}")

if __name__ == "__main__": main()
```

